script
const parseNestedParensBrackets = (paren_bracket_string) => {
  // Using regular expression, separate the string into groups based on commas.
  const groups = paren_bracket_string.split(', ');

  // Create an array to store the maximum level of nesting for each group.
  const nestingLevels = [];

  // Iterate over each group.
  for (let group of groups) {
    // Initialize count and maxCount to 0.
    let count = 0, maxCount = 0;

    // Iterate over each character in the group.
    for (let char of group) {
      // If it's an open paren or bracket, increment count.
      if (char === '(' || char === '[') {
        count++;
      } 
      // Else if it's a close paren or bracket, decrement count.
      else if (char === ')' || char === ']') {
        count--;
      }

      // If the current count is greater than maxCount, update maxCount.
      if (count > maxCount) {
        maxCount = count;
      }
    }

    // Push the maxCount for the current group into the nestingLevels array.
    nestingLevels.push(maxCount);
  }

  // Return the array of maximum nesting levels.
  return nestingLevels;
}

