def partition(lst, low, high):
    """Partition the list in-place and return the index of the pivot."""
    pivot = lst[high]
    i = low - 1

    for j in range(low, high):
        if lst[j] < pivot:
            i += 1
            lst[i], lst[j] = lst[j], lst[i]

    lst[i+1], lst[high] = lst[high], lst[i+1]
    return i + 1

def quickselect(lst, k, low=None, high=None):
    """Return the k-th smallest element of lst. lst is modified."""
    if low is None: low = 0
    if high is None: high = len(lst) - 1
    pivot = partition(lst, low, high)
    if pivot == k:
        return lst[k]
    elif pivot > k:
        return quickselect(lst, k, low, pivot-1)
    else:
        return quickselect(lst, k, pivot+1, high)

def median(lst):
    n = len(lst)
    if n % 2 == 1:
        return quickselect(lst, n // 2)
    else:
        return (quickselect(lst, n // 2 - 1) + quickselect(lst, n // 2)) / 2

