import java.util.*;

class Solution {
    public Map<String, Integer> histogram(String test) {
        String[] words = test.split(" ");
        Map<String, Integer> freqMap = new HashMap<>();
        Stack<Integer> multiplier = new Stack<>();
        Integer lastFreq = 0;

        for (String word : words) {
            if (word.equals("#")) {
                if (!multiplier.isEmpty()) {
                    Integer prev = multiplier.pop();
                    multiplier.push(prev*prev);
                } else {
                    multiplier.push(lastFreq*lastFreq);
                }
            } else {
                if (freqMap.containsKey(word)) {
                    freqMap.put(word, freqMap.get(word)+1);
                } else {
                    freqMap.put(word, 1);
                }
                lastFreq = freqMap.get(word);
            }

            if (!multiplier.isEmpty()) {
                freqMap.put(words[multiplier.size()-1], multiplier.peek());
            }
        }

        Integer maxFreq = Collections.max(freqMap.values());
        Map<String, Integer> result = new HashMap<>();
        for (String key : freqMap.keySet()) {
            if (freqMap.get(key).equals(maxFreq)) {
                result.put(key, maxFreq);
            }
        }

        return result;
    }
}

